function computeQuiz(ans){
  var c={v:0,a:0,r:0,h:0},n=0;
  QZ.forEach(function(q,i){if(!q.pace&&!q.order&&ans[i]){c[ans[i]]++;n++}});
  if(has("visual")){c.a+=1.5;c.v=Math.max(0,c.v-1)}
  if(has("hearing")){c.v+=1;c.a=Math.max(0,c.a-1)}
  if(has("dyslexia")){c.v+=.5;c.a+=.5}
  var tot=c.v+c.a+c.r+c.h||1,pct={};
  Object.keys(c).forEach(function(k){pct[k]=Math.round(c[k]/tot*100)});
  var order=Object.keys(pct).sort(function(a,b){return pct[b]-pct[a]});
  var sess=+(ans[6]||20);if(has("adhd"))sess=Math.min(sess,15);
  return {pct:pct,primary:order[0],secondary:order[1],session:sess,start:ans[7]||"steps"};
}
