/* ---------- speech ---------- */
var sp={timer:null,el:null,orig:null};
function stopSpeak(){try{window.speechSynthesis&&speechSynthesis.cancel()}catch(e){}
  if(sp.timer)clearInterval(sp.timer);sp.timer=null;if(sp.el&&sp.orig!==null)sp.el.innerHTML=sp.orig;sp.el=null;sp.orig=null;cap(null);
  var wv0=document.getElementById("waves");if(wv0)wv0.classList.remove("on");if(S.sumPlaying){S.sumPlaying=false;var b=document.getElementById("sum-play");if(b)b.innerHTML=ic("play")+L("استمع إلى الملخص","Play summary")}}
function speak(text,lang,el,onEnd,onWord){stopSpeak();
  var words=text.split(/\s+/).filter(Boolean);
  if(el){sp.el=el;sp.orig=el.innerHTML;el.innerHTML=words.map(function(w,i){return '<span class="w" data-i="'+i+'">'+esc(w)+'</span>'}).join(" ")}
  try{if("speechSynthesis" in window){var u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=.95;var vs=speechSynthesis.getVoices()||[];var v=vs.find(function(x){return x.lang&&x.lang.toLowerCase().indexOf(lang.slice(0,2).toLowerCase())===0});if(v)u.voice=v;speechSynthesis.speak(u)}}catch(e){}
  var i=0;sp.timer=setInterval(function(){
    if(sp.el){var p=sp.el.querySelector(".w.hl");if(p)p.classList.remove("hl");var c=sp.el.querySelector('.w[data-i="'+i+'"]');if(c)c.classList.add("hl")}
    cap(words.slice(Math.max(0,i-5),i+6).join(" "));if(onWord)onWord(i);i++;
    if(i>words.length){clearInterval(sp.timer);sp.timer=null;setTimeout(function(){if(sp.el&&sp.orig!==null)sp.el.innerHTML=sp.orig;sp.el=null;sp.orig=null;cap(null);if(onEnd)onEnd()},300)}
  },400)}
function cap(t){var b=document.getElementById("capbar");if(!b)return;if(t&&S.a11y.captions){b.hidden=false;b.firstChild.textContent=t}else b.hidden=true}
function uiLang(){return S.lang==="ar"?"ar-SA":"en-US"}

