function renderExp(){
  var box=document.getElementById("exp");if(!box)return;var e=S.exp,h="",rec=S.quiz?FMT[S.quiz.primary].mode:null;
  if(!e.lesson){h='<div class="row"><button class="btn primary" data-act="exp-lesson">'+ic("leaf")+L("العلوم: الدرس 4، البناء الضوئي","Science: Lesson 4, Photosynthesis")+'</button><label class="btn file">'+ic("upload")+L("ارفع صفحة من الكتاب","Upload a textbook page")+'<input type="file" accept="image/*,application/pdf" data-in="exp-upload"></label></div>';box.innerHTML=h;return}
  h+='<p class="small muted" style="margin-bottom:8px">'+L("اضغط على الفقرة التي لم تفهمها:","Tap the paragraph you didn't understand:")+'</p><div class="stack" style="gap:8px">'+PASSAGE.map(function(p,i){return '<button class="para" data-act="exp-para" data-i="'+i+'" aria-pressed="'+(e.para===i)+'">'+T(p.t)+'</button>'}).join("")+'</div>';
  if(e.para!==null){
    h+='<p class="small muted" style="margin:16px 0 8px">'+L("طريقة الشرح:","Explanation format:")+'</p><div class="modes">'+[["text","text",L("نص مبسّط","Simple text")],["audio","vol",L("شرح صوتي","Audio")],["illus","image",L("رسم توضيحي","Illustration")],["steps","list",L("خطوات قصيرة","Short steps")],["inter","hand",L("نشاط تفاعلي","Interactive")]]
     .map(function(m){return '<button class="mode" data-act="exp-mode" data-m="'+m[0]+'" aria-pressed="'+(e.mode===m[0])+'">'+ic(m[1])+m[2]+(rec===m[0]?' <span class="rec">'+L("مقترح لك","For you")+'</span>':'')+'</button>'}).join("")+'</div>';
  }
  if(e.mode){var p=PASSAGE[e.para];
    h+='<div class="explain" style="margin-top:14px"><p style="font-weight:600;color:var(--ink)">'+T(p.f)+'</p>'+explainBody(e.mode)+aiFoot(L("كتاب العلوم، الصف السابع، ص 45","Science textbook, Grade 7, p. 45"))+'</div>';
    h+='<h4 style="margin:18px 0 10px">'+L("تدرّب: 3 أسئلة متدرجة","Practise: 3 graded questions")+'</h4><div class="stack" style="gap:10px">'+QS.map(function(q,qi){var an=e.ans[qi];
      var o=q.o.map(function(op,oi){var cls=an===undefined?"":(oi===q.a&&an===q.a?"right":(oi===an?"wrong":""));return '<button class="opt '+cls+'" data-act="exp-ans" data-q="'+qi+'" data-o="'+oi+'"'+(an===q.a?" disabled":"")+'>'+T(op)+'</button>'}).join("");
      var fb="";if(an!==undefined&&an===q.a)fb='<p style="color:var(--ok);font-weight:600;display:flex;gap:6px;align-items:center">'+ic("check")+L("إجابة صحيحة.","Correct.")+'</p>';
      else if(an!==undefined){var alt=e.mode==="illus"?"steps":"illus";fb='<div class="reex"><b style="color:var(--ink)">'+L("لنجرّبها بطريقة أخرى","Let's try another way")+'</b><p>'+T(q.h)+'</p>'+explainBody(alt,true)+'</div>'}
      return '<div class="q"><div class="row"><span class="tag plain">'+T(q.lv)+'</span><b style="color:var(--ink)">'+T(q.t)+'</b></div><div class="opts">'+o+'</div>'+fb+'</div>'}).join("")+'</div>';
    if(QS.every(function(q,i){return e.ans[i]===q.a}))h+='<div class="okbox" style="margin-top:12px">'+ic("check")+'<span>'+L("أنهيتِ التدريب، وتحدّث ملفك، ووصل تقدّمك إلى معلمتك.","Practice done. Your profile is updated and your teacher can see your progress.")+'</span></div>';
    h+='<div style="margin-top:12px">'+noDiag()+'</div>'}
  box.innerHTML=h;decorate(box)}
function explainBody(m,mini){
  if(m==="text")return '<p data-read>'+T(EXP_TEXT)+'</p>';
  if(m==="audio")return '<div class="row"><button class="btn primary sm" data-act="exp-play">'+ic("play")+L("استمع إلى الشرح","Play the explanation")+'</button><span class="small muted">'+L("تُظلَّل الكلمات أثناء القراءة","Words are highlighted as they're read")+'</span></div><p id="exp-audio-text">'+T(EXP_TEXT)+'</p>';
  if(m==="steps")return '<ol>'+EXP_STEPS.map(function(s){return '<li>'+T(s)+'</li>'}).join("")+'</ol>';
  if(m==="illus")return illus();
  if(m==="inter"){if(mini)return illus();var it=S.exp.interact,right=MATCH.filter(function(x){return it[x.k]===x.a}).length;
    return '<p>'+L("ما الذي يدخل إلى الورقة، وما الذي يخرج منها؟","What goes into the leaf, and what comes out?")+'</p><div class="match">'+MATCH.map(function(x){var v=it[x.k];var st=v===undefined?"":(v===x.a?'<span class="tag ok">'+L("صحيح","Right")+'</span>':'<span class="tag bad">'+L("حاول مرة أخرى","Try again")+'</span>');
      return '<div class="mrow"><b>'+T(x.t)+'</b><div class="row">'+st+'<button class="btn sm" data-act="exp-int" data-k="'+x.k+'" data-v="in">'+L("يدخل","Goes in")+'</button><button class="btn sm" data-act="exp-int" data-k="'+x.k+'" data-v="out">'+L("يخرج","Comes out")+'</button></div></div>'}).join("")+'</div><p class="small muted num">'+L("صحيح: ","Correct: ")+right+' / 5</p>'}
  return ""}
