function b64(s){return Uint8Array.from(atob(s),function(c){return c.charCodeAt(0)})}
function hex(buf){return Array.from(new Uint8Array(buf)).map(function(b){return b.toString(16).padStart(2,"0")}).join("")}
function digest(s){return crypto.subtle.digest("SHA-256",new TextEncoder().encode(s)).then(hex)}
function openSecure(code){
  return crypto.subtle.importKey("raw",new TextEncoder().encode(code),"PBKDF2",false,["deriveKey"]).then(function(base){
    return crypto.subtle.deriveKey({name:"PBKDF2",salt:b64(K.s),iterations:K.n,hash:"SHA-256"},base,{name:"AES-GCM",length:256},false,["decrypt"])}).then(function(key){
    return crypto.subtle.decrypt({name:"AES-GCM",iv:b64(K.i)},key,b64(K.d))}).then(function(pt){return JSON.parse(new TextDecoder().decode(pt))})}
function vSecure(){return '<div id="secure-root">'+(S.secure?S.secure[S.lang]:"")+'</div>'}

