function vPrivacy(){
  return '<main id="main" class="wrap page"><h1 style="margin-bottom:16px">'+L("الخصوصية والموافقات","Privacy and consent")+'</h1><div class="grid g2" style="align-items:start">'+
   '<section class="card"><h3 style="margin-bottom:10px">'+ic("eye")+L("من اطّلع على بيانات سارة","Who accessed Sara's data")+'</h3><ul class="log">'+LOG.map(function(r){return '<li><div><b>'+T(r.w)+'</b><div class="muted">'+T(r.d)+'</div></div><span class="muted num">'+T(r.t)+'</span></li>'}).join("")+'</ul></section>'+
   '<section class="card"><h3 style="margin-bottom:10px">'+ic("lock")+L("المشاركة مع الخدمات","Sharing with services")+'</h3>'+CONSENT.map(function(k){return '<div class="setting"><div class="txt"><b id="cl-'+k.k+'">'+T(k.t)+'</b></div><button class="sw" role="switch" aria-labelledby="cl-'+k.k+'" aria-checked="'+S.consent[k.k]+'" data-act="consent" data-k="'+k.k+'"></button></div>'}).join("")+'</section>'+
   '<section class="card stack" id="p-transfer"><h3>'+ic("move")+L("ملف ينتقل مع الطالب","A profile that moves with the student")+'</h3><div id="transfer"></div></section>'+
   '<section class="card stack"><h3>'+ic("x")+L("حذف سجل احتياجات الدعم","Delete the support-needs record")+'</h3><p class="small muted">'+L("يحق لك حذف السجل أو حجبه في أي وقت، فيبدأ ابنك من جديد في أي مدرسة.","You can delete or hide this record at any time, so your child can start fresh at any school.")+'</p><button class="btn" data-act="needs-delete" style="justify-self:start">'+L("احذف السجل","Delete the record")+'</button></section></div></main>'}
function classTabs(){return S.classes.length>1?'<div class="tabs" role="tablist">'+S.classes.map(function(id){var c=CLASSES.find(function(x){return x.id===id});return '<button role="tab" aria-selected="'+(S.tclass===id)+'" data-act="tcl" data-id="'+id+'">'+T(c.n)+'</button>'}).join("")+'</div>':''}
function vProgress(){
  if(S.classes.indexOf(S.tclass)<0)S.tclass=S.classes[0];
  var cl=CLASSES.find(function(c){return c.id===S.tclass}),d=classData(cl),lv=[null,L("متقن","Mastered"),L("جيد","Good"),L("يحتاج مراجعة","Needs review"),L("يحتاج دعمًا","Needs support")];
  return '<main id="main" class="wrap page"><div class="page-head"><div><h1>'+L("تقدّم الفصل ","Class progress ")+T(cl.n)+'</h1><p class="muted">'+L("نسبة الإتقان لكل مهارة","Mastery per skill")+'</p></div>'+classTabs()+'</div>'+
   '<section class="card"><div class="tbl-wrap" style="max-height:420px;overflow:auto"><table class="heat"><thead><tr><th>'+L("الطالبة","Student")+'</th>'+SKILLS.map(function(s){return '<th>'+T(s)+'</th>'}).join("")+'</tr></thead><tbody>'+d.names.map(function(n,i){return '<tr><td><b style="color:var(--ink);font-weight:600">'+T(n)+'</b></td>'+d.rows[i].map(function(v){var l=lvl(v);return '<td><span class="c l'+l+' num" title="'+lv[l]+'">'+v+'</span></td>'}).join("")+'</tr>'}).join("")+'</tbody></table></div><div class="legend">'+[1,2,3,4].map(function(l){return '<span><i class="l'+l+'"></i>'+lv[l]+'</span>'}).join("")+'</div></section>'+
   '<section class="card" style="margin-top:16px"><div class="card-head"><h3>'+ic("move")+L("طالبات منتقلات إلى فصلك","Students joining your class")+'</h3></div><div class="grid g2">'+
    [[L("ليان","Leen"),L("من مدرسة أخرى","From another school"),L("القراءة، والعمل في مجموعات","Reading, group work"),L("وقت إضافي في المسائل الكلامية","Extra time on word problems"),L("قراءة صوتية، وخط ميسّر للقراءة","Read-aloud, reading-friendly font")],[L("جود","Joud"),L("من الصف السادس","From Grade 6"),L("الحساب الذهني","Mental arithmetic"),L("تعليمات مقسّمة إلى خطوات","Instructions in steps"),L("بيئة هادئة، وتنبيه قبل أي تغيير","A calm space, with notice before changes")]]
    .map(function(p){return '<div class="card prof" style="background:var(--paper)"><div class="row" style="justify-content:space-between"><b style="color:var(--ink)">'+p[0]+'</b><span class="tag ok">'+L("بموافقة ولي الأمر","Parent consented")+'</span></div><p class="small muted" style="margin-block:4px 8px">'+p[1]+'</p><dl><dt>'+L("نقاط القوة","Strengths")+'</dt><dd>'+p[2]+'</dd><dt>'+L("تحتاج دعمًا في","Support")+'</dt><dd>'+p[3]+'</dd><dt>'+L("ما يساعدها","What helps")+'</dt><dd>'+p[4]+'</dd></dl></div>'}).join("")+'</div><p class="note" style="margin-top:12px">'+ic("shield")+'<span>'+L("يرى المعلم ما تحتاجه الطالبة للتعلّم فقط، دون اسم الحالة أو أي تشخيص.","Teachers see only what a student needs to learn, never the condition's name or a diagnosis.")+'</span></p></section></main>'}
function vWorksheet(){
  return '<main id="main" class="wrap page"><div class="page-head"><div><h1>'+L("ورقة عمل واحدة بثلاث نسخ","One worksheet, three versions")+'</h1><p class="muted">'+L("اختاري الموضوع والمستوى، ويُعدّ مداد الورقة ونسخها الميسّرة. موافقتك بضغطة واحدة.","Pick the topic and level; Midad drafts the worksheet and its accessible versions. You approve with one tap.")+'</p></div></div><section class="card" id="t-ws"><div id="ws"></div></section></main>'}
function groupsFor(){if(S.role==="parent")return kidsList().map(function(k){return k==="sara"?"g7b":"g4a"});return S.classes.map(function(id){return "g"+id})}
function allMsgs(){return MSG_SEED.concat(sload("msgs",[]))}
function maskContact(t){var m=t.replace(/[\w.+-]+@[\w-]+\.[\w.]+/g,"••••").replace(/\+?\d[\d\s-]{6,}\d/g,"••••");return {t:m,masked:m!==t}}
function newFor(role){var ms=sload("msgs",[]);return role==="teacher"?ms.some(function(m){return m.from==="parent"&&!m.answered}):ms.some(function(m){return m.from==="teacher"})}
function vChat(){
  var gs=groupsFor();if(gs.indexOf(S.cg)<0)S.cg=gs[0];var g=GROUPS[S.cg],teacher=S.role==="teacher";
  var me=teacher?null:(S.cg==="g7b"?"sara":"omar");
  var ms=allMsgs().map(function(m,i){m._i=i;return m}).filter(function(m){if(m.g!==S.cg)return false;if(!m.priv)return true;if(teacher)return true;return m.kid===me});
  var list=ms.map(function(m){var mine=teacher?m.from==="teacher"&&m.user:m.from==="parent"&&m.kid===me&&m.user;var txt=m.user?esc(m.text):T(m.t);
    var who=m.from==="teacher"?T(g.teacher):(m.kid?L("ولي أمر ","Parent of ")+T(KIDN[m.kid]||["",""]):T(m.name));
    return '<div class="msg'+(mine?" mine":"")+(m.from==="teacher"?" teacher":"")+(m.pin?" pin":"")+(m.priv?" priv":"")+'"><div class="who"><b>'+who+'</b><span class="num">'+(m.user?L("الآن","Now"):T(m.time))+'</span>'+(m.pin?'<span class="tag gold">'+L("مثبّتة","Pinned")+'</span>':'')+(m.priv?'<span class="tag">'+ic("lock")+L("خاص","Private")+'</span>':'')+(teacher&&m.from==="parent"&&!m.answered&&m.user?'<span class="tag bad">'+L("بانتظار الرد","Awaiting reply")+'</span>':'')+'</div><div class="bubble">'+txt+'</div>'+(m.masked?'<span class="small muted">'+L("حُجبت معلومات تواصل شخصية تلقائيًا.","Personal contact details were hidden automatically.")+'</span>':'')+(teacher&&m.from==="parent"?'<div class="row"><button class="linkbtn" data-act="reply" data-i="'+m._i+'">'+L("ردّ","Reply")+'</button></div>':'')+'</div>'}).join("");
  var rt=S.replyTo!=null?allMsgs()[S.replyTo]:null;
  return '<main id="main" class="wrap page"><div class="page-head"><div><h1>'+L("التواصل","Messages")+'</h1><p class="muted">'+(teacher?L("مجموعات فصولك مع أولياء الأمور","Your class groups with parents"):L("مجموعات فصول أبنائك مع المعلمين","Your children's class groups with teachers"))+'</p></div>'+(gs.length>1?'<div class="tabs" role="tablist">'+gs.map(function(x){return '<button role="tab" aria-selected="'+(S.cg===x)+'" data-act="cg" data-g="'+x+'">'+groupLabel(x)+'</button>'}).join("")+'</div>':'')+'</div>'+
   '<section class="card"><div class="card-head"><div><h3>'+ic("users")+T(GROUPS[S.cg].n)+'</h3><p class="small muted">'+T(g.teacher)+L(" و"," and ")+g.parents+L(" ولي أمر تحقّق مداد من صلتهم بطلبة الفصل"," parents verified as linked to students in this class")+'</p></div></div>'+
   '<p class="note" style="margin-bottom:12px">'+ic("shield")+'<span>'+L("للاستفسارات الدراسية فقط. الرد خلال يوم عمل، من الأحد إلى الخميس. لا تشارك أرقام الهواتف أو معلومات صحية في المجموعة، واستخدم «خاص» للأمور الشخصية. كل الرسائل محفوظة في سجل المدرسة.","For study questions only. Replies within one working day, Sunday to Thursday. Don't share phone numbers or health details in the group; use Private for personal matters. All messages are kept in the school's record.")+'</span></p>'+
   '<div class="msgs" id="msgs">'+list+'</div>'+
   '<form class="composer" data-form="msg">'+(rt?'<p class="small row">'+L("ردّ على: ","Replying to: ")+'<b>'+(rt.kid?L("ولي أمر ","Parent of ")+T(KIDN[rt.kid]):T(rt.name))+'</b>'+(rt.priv?' <span class="tag">'+L("خاص","Private")+'</span>':'')+'<button class="linkbtn" type="button" data-act="reply-cancel">'+L("إلغاء","Cancel")+'</button></p>':'')+
    '<label class="sr" for="m-text">'+L("رسالتك","Your message")+'</label><textarea id="m-text" maxlength="500" placeholder="'+(teacher?L("اكتبي ردك أو إعلانًا للمجموعة…","Write a reply or an announcement…"):L("اكتب استفسارك…","Write your question…"))+'"></textarea>'+
    '<div class="row" style="justify-content:space-between">'+(teacher?'<span></span>':'<label class="row" style="gap:8px;cursor:pointer"><input type="checkbox" id="m-priv" style="width:20px;height:20px;accent-color:var(--accent)">'+L("خاص للمعلمة فقط","Private, teacher only")+'</label>')+'<button class="btn primary" type="submit">'+ic("chat")+L("أرسل","Send")+'</button></div></form></section></main>'}

function drop(h){return '<svg class="dropin" width="'+Math.round(h*.8)+'" height="'+h+'" viewBox="0 0 22 28" aria-hidden="true"><path d="M11 1C11 1 2 12 2 18a9 9 0 0 0 18 0C20 12 11 1 11 1z" fill="#F26B1D"/></svg>'}
function sideItems(){
  if(S.role==="student")return [["student","user",L("الرئيسية","Home")],["schedule","cal",L("جدولي وواجباتي","My schedule")],["learn","help",L("اشرح لي درسًا","Explain a lesson")],["videos","video",L("فيديوهاتي","My videos")]].concat(hasPOD()?[["tools","ear",L("أدوات الإتاحة","Access tools")]]:[]).concat([["passport","pass",L("جواز الإتاحة","Accessibility Passport")]]);
  if(S.role==="parent")return [["parent","user",L("الرئيسية","Home")],["kids","layers",L("أبنائي اليوم","My children today")],["voice","vol",L("الملخص الصوتي","Voice summary")],["chat","chat",L("التواصل مع المعلمين","Message teachers")],["ask","spark",L("اسأل المساعد","Ask the assistant")],["privacy","lock",L("الخصوصية","Privacy")]];
  if(S.role==="teacher")return [["teacher","user",L("الرئيسية","Home")],["progress","chart",L("تقدّم الفصل","Class progress")],["worksheet","doc",L("ورقة عمل","Worksheet")],["chat","chat",L("التواصل مع أولياء الأمور","Message parents")],["classes","users",L("استلام الفصول","Class handover")]];
  return []}
function inOnboarding(){return (S.role==="student"&&(!S.needsDone||!S.quiz||!S.passportDone))||(S.role==="parent"&&!S.verified)||(S.role==="teacher"&&!S.classes.length)}
function sidebar(){
  var items=inOnboarding()?[]:sideItems();
  var who=S.role==="student"?L("سارة · الصف السابع","Sara · Grade 7"):S.role==="parent"?L("ولي أمر سارة وعمر","Parent of Sara and Omar"):L("أ. مريم · الرياضيات","Ms. Maryam · Math");
  return '<aside class="side"><a class="logo" href="#'+(inOnboarding()?S.view:homeFor())+'">'+drop(24)+'<b>'+L("مداد","Midad")+'</b></a><p class="who">'+who+'</p><nav aria-label="'+L("القائمة","Menu")+'">'+items.map(function(n){return '<a href="#'+n[0]+'"'+(S.view===n[0]?' aria-current="page"':'')+'>'+ic(n[1])+'<span>'+n[2]+'</span></a>'}).join("")+'</nav>'+
   '<div class="bottom"><button class="sbtn" data-act="blind" aria-pressed="'+(!!S.a11y.blind)+'">'+ic("eye")+'<span class="lbl">'+(S.a11y.blind?L("وضع المكفوفين: مفعّل","Blind mode: on"):L("وضع المكفوفين","Blind mode"))+'</span></button><a class="sbtn" href="#settings"'+(S.view==="settings"?' aria-current="page"':'')+'>'+ic("gear")+'<span class="lbl">'+L("الإعدادات","Settings")+'</span></a><button class="sbtn" data-act="lang">'+ic("globe")+'<span class="lbl">'+L("English","العربية")+'</span></button><button class="sbtn" data-act="logout">'+ic("logout","flip")+'<span class="lbl">'+L("خروج","Sign out")+'</span></button></div></aside>'}
function heroArt(){return '<svg viewBox="0 0 480 380" role="img" aria-label="'+L("رسم: طالبة أمام حاسوب، وحولها بطاقات الواجبات والدروس والنتائج","Illustration: a student at a computer, surrounded by homework, lesson and result cards")+'">'+
 '<circle cx="250" cy="200" r="160" fill="#1B2F57"/><rect x="120" y="250" width="270" height="14" rx="7" fill="#3A4E78"/><rect x="150" y="120" width="210" height="132" rx="12" fill="#FFFFFF"/><rect x="166" y="136" width="178" height="18" rx="6" fill="#FFE3CF"/><rect x="166" y="164" width="120" height="10" rx="5" fill="#D5DDE8"/><rect x="166" y="182" width="150" height="10" rx="5" fill="#D5DDE8"/><rect x="166" y="206" width="70" height="30" rx="8" fill="#F26B1D"/>'+
 '<circle cx="250" cy="300" r="26" fill="#FFB27D"/><path d="M210 380c0-40 18-62 40-62s40 22 40 62z" fill="#F26B1D"/><path d="M226 296c0-24 10-36 24-36s26 10 26 30c-12-6-30-6-50 6z" fill="#0F1F3D"/>'+
 '<g class="floaty"><rect x="30" y="70" width="150" height="70" rx="14" fill="#FFFFFF"/><circle cx="150" cy="105" r="16" fill="#FFE3CF"/><path d="M143 105l5 5 9-10" stroke="#C2500F" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/><rect x="46" y="92" width="72" height="9" rx="4" fill="#0F1F3D"/><rect x="46" y="110" width="50" height="8" rx="4" fill="#D5DDE8"/></g>'+
 '<g class="floaty2"><rect x="340" y="40" width="130" height="64" rx="14" fill="#F26B1D"/><rect x="356" y="58" width="70" height="9" rx="4" fill="#0F1F3D"/><rect x="356" y="76" width="96" height="9" rx="4" fill="#FFE3CF"/></g>'+
 '<g class="floaty"><rect x="350" y="270" width="120" height="76" rx="14" fill="#FFFFFF"/><rect x="366" y="314" width="14" height="18" rx="3" fill="#F26B1D"/><rect x="386" y="300" width="14" height="32" rx="3" fill="#0F1F3D"/><rect x="406" y="292" width="14" height="40" rx="3" fill="#FF9A57"/><rect x="426" y="306" width="14" height="26" rx="3" fill="#3A4E78"/></g></svg>'}
function vSchedule(){
  return '<main id="main" class="wrap page"><div class="page-head"><div><p class="eyebrow">'+L("ميزة · جدولي وواجباتي","Feature · My schedule")+'</p><h1>'+L("كل واجباتك ومواعيدك في مكان واحد","All your homework and dates in one place")+'</h1><p class="muted">'+L("مجمّعة من 4 أنظمة، ومرتبة حسب الموعد.","Gathered from 4 systems, sorted by date.")+'</p></div></div>'+
   '<div class="grid g2" style="align-items:start"><section class="card"><h3 style="margin-bottom:12px">'+ic("cal")+L("هذا الأسبوع","This week")+'</h3>'+feedList(FEED.filter(function(f){return f.child==="sara"&&!f.parentOnly}))+'</section>'+
   '<section class="card"><h3 style="margin-bottom:12px">'+ic("chart")+L("موادي","My subjects")+'</h3><div class="subj">'+SUBJ.map(function(s){return bar(T(s[0]),s[1])}).join("")+'</div></section></div></main>'}
function kidTabs(ks){return ks.length>1?'<div class="tabs" role="tablist" style="justify-self:start;background:#1B2F57">'+ks.map(function(k){return '<button role="tab" aria-selected="'+(S.child===k)+'" data-act="child" data-c="'+k+'" style="'+(S.child===k?'':'color:#C9D3E6')+'">'+T(KIDS[k].n)+' · '+T(KIDS[k].g)+'</button>'}).join("")+'</div>':''}
function vKids(){
  var ks=kidsList();if(ks.indexOf(S.child)<0)S.child=ks[0];
  return '<main id="main" class="wrap page"><div class="page-head"><div><p class="eyebrow">'+L("ميزة · أبنائي اليوم","Feature · My children today")+'</p><h1>'+L("كل شيء عن ","Everything about ")+T(KIDS[S.child].n)+'</h1><p class="muted">'+L("من 4 أنظمة، في قائمة واحدة.","From 4 systems, in one list.")+'</p></div>'+(ks.length>1?'<div class="tabs" role="tablist">'+ks.map(function(k){return '<button role="tab" aria-selected="'+(S.child===k)+'" data-act="child" data-c="'+k+'">'+T(KIDS[k].n)+'</button>'}).join("")+'</div>':'')+'</div><section class="card"><div id="pfeed"></div></section></main>'}
function vVoice(){
  return '<main id="main" class="wrap page narrow"><div class="page-head"><div><p class="eyebrow">'+L("ميزة · الملخص الصوتي","Feature · Voice summary")+'</p><h1>'+L("يومك في دقيقة، بلغتك","Your day in one minute, in your language")+'</h1><p class="muted">'+L("يجمع واجبات اليوم ومواعيد الغد والتعاميم من كل الأنظمة.","It gathers today's homework, tomorrow's dates and circulars from every system.")+'</p></div></div>'+
   '<section class="card voice2 stack" id="p-voice"><div class="row" style="gap:16px"><button class="btn primary" id="sum-play" data-act="sum-play" style="min-height:56px;padding:0 24px">'+ic("play")+L("استمع إلى الملخص","Play summary")+'</button><div class="waves" id="waves" aria-hidden="true">'+"<i></i>".repeat(7)+'</div></div>'+
   '<label class="field" for="sum-lang">'+L("اللغة","Language")+'<select id="sum-lang" data-in="sumlang">'+Object.keys(SUMMARY).map(function(k){return '<option value="'+k+'"'+(S.sumLang===k?" selected":"")+'>'+SUMMARY[k].n+'</option>'}).join("")+'</select></label>'+
   '<div class="tr" id="sum-text" dir="'+SUMMARY[S.sumLang].dir+'" lang="'+SUMMARY[S.sumLang].code+'">'+SUMMARY[S.sumLang].t+'</div></section></main>'}

function rolesHtml(){return '<div class="roles2">'+[["student","o","grad",L("طالب","Student"),L("دروسك وواجباتك وفيديوهاتك، بطريقتك","Your lessons, homework and videos, your way"),L("ادخل كطالب","Continue as a student")],["parent","n","users",L("ولي أمر","Parent"),L("تابع أبناءك وتواصل مع المعلمين من مكان واحد","Follow your children and message teachers in one place"),L("ادخل كولي أمر","Continue as a parent")],["teacher","o","board",L("معلم","Teacher"),L("فصولك وطلابك وأوراق العمل الميسّرة","Your classes, students and accessible worksheets"),L("ادخل كمعلم","Continue as a teacher")]]
    .map(function(r,i){return '<button class="role2 '+r[1]+'" data-act="role" data-r="'+r[0]+'"><span class="ri">'+ic(r[2])+'</span><b>'+r[3]+'</b><span class="muted">'+r[4]+'</span><span class="go2">'+r[5]+' ←</span>'+(S.a11y.blind?'<span class="tag plain" style="justify-self:start">'+L("اضغط "+(i+1),"Press "+(i+1))+'</span>':'')+'</button>'}).join("")+'</div>'}
function vStart(){
  return '<main id="main" class="wrap page"><div style="text-align:center;display:grid;gap:10px;justify-items:center;margin-bottom:28px"><span class="eyebrow">'+L("ابدأ من هنا","Start here")+'</span><h1 tabindex="-1">'+L("من أنت؟","Who are you?")+'</h1><p class="muted">'+L("اختر نوع حسابك لتبدأ.","Choose your account type to begin.")+'</p></div>'+rolesHtml()+
   '<section class="card" style="margin-top:24px;display:flex;gap:16px;align-items:center;flex-wrap:wrap;background:var(--side);color:#FFFFFF;border:0"><span class="ri" style="width:52px;height:52px;border-radius:16px;background:#F26B1D;color:#0F1F3D;display:grid;place-items:center">'+ic("eye")+'</span><div style="flex:1;min-width:220px;display:grid;gap:4px"><b style="font-size:1.1rem">'+L("هل أنت كفيف أو ضعيف البصر؟","Are you blind or low vision?")+'</b><span style="color:#C9D3E6">'+L("فعّل وضع المكفوفين: يقرأ مداد كل صفحة بصوت، وتتنقل بالأرقام ولوحة المفاتيح.","Turn on blind mode: Midad reads every page aloud, and you move around with number keys and the keyboard.")+'</span></div><button class="btn primary" data-act="blind" aria-pressed="'+(!!S.a11y.blind)+'">'+(S.a11y.blind?L("وضع المكفوفين مفعّل","Blind mode is on"):L("فعّل وضع المكفوفين","Turn on blind mode"))+'</button></section></main>'}

/* ---------- blind mode ---------- */
function liveSay(t){var r=document.getElementById("sr-live");if(r){r.textContent="";setTimeout(function(){r.textContent=t},50)}}
function blindSpeak(t){liveSay(t);if(S.a11y.blind)speak(t,uiLang(),null)}
function shortcutTargets(){if(S.authed&&!inOnboarding())return sideItems().map(function(n){return [n[0],n[2]]});if(S.view==="home"||S.view==="start")return [["role:student",L("طالب","Student")],["role:parent",L("ولي أمر","Parent")],["role:teacher",L("معلم","Teacher")]];return []}
function pageSummary(){var h=document.querySelector("main h1"),t=h?h.textContent.trim():"";var items=shortcutTargets();
  var s=L("أنت في صفحة: ","You are on: ")+(t||L("مداد","Midad"))+". ";
  if(items.length)s+=items.map(function(it,i){return L("اضغط "+(i+1)+": "+it[1],"Press "+(i+1)+": "+it[1])}).join(L("، ",", "))+". ";
  s+=L("اضغط حرف ق لقراءة الصفحة كاملة، وحرف ح لسماع كل الاختصارات، وزر Tab للتنقل بين العناصر.","Press R to read the whole page, H to hear all shortcuts, and Tab to move between items.");return s}
function readPage(){var m=document.querySelector("main");if(!m)return;var txt=Array.from(m.querySelectorAll("h1,h2,h3,p,li,b,button,a,label")).filter(function(e){return e.offsetParent!==null&&!e.closest("button,a")||e.matches("button,a")}).map(function(e){return (e.getAttribute("aria-label")||e.textContent).trim().replace(/[.،:؟?!]+$/,"")}).filter(Boolean);
  var seen={},out=[];txt.forEach(function(x){if(!seen[x]){seen[x]=1;out.push(x)}});blindSpeak(out.join(". ").slice(0,1800))}
function shortcutHelp(){blindSpeak(L("الاختصارات: الأرقام من 1 إلى 9 تفتح عناصر القائمة. حرف ق يقرأ الصفحة. حرف ح يقرأ هذه المساعدة. حرف ر يرجع للصفحة السابقة. زر Escape يوقف القراءة. وزر Tab ينقلك بين العناصر وينطق كل عنصر.","Shortcuts: numbers 1 to 9 open menu items. R reads the page. H reads this help. B goes back. Escape stops reading. Tab moves between items and says each one."))}
function roleWord(e){var r=e.getAttribute("role"),t=e.tagName;if(r==="switch")return L("مفتاح ","switch ")+(e.getAttribute("aria-checked")==="true"?L("مفعّل","on"):L("غير مفعّل","off"));if(r==="checkbox")return L("خيار ","option ")+(e.getAttribute("aria-checked")==="true"?L("محدد","selected"):L("غير محدد","not selected"));if(t==="A")return L("رابط","link");if(t==="BUTTON")return L("زر","button");if(t==="SELECT")return L("قائمة اختيار","list");if(t==="INPUT"&&e.type==="file")return L("زر رفع ملف","file upload button");if(t==="INPUT"&&e.type==="checkbox")return L("خيار ","checkbox ")+(e.checked?L("محدد","checked"):L("غير محدد","not checked"));if(t==="INPUT"&&e.type==="range")return L("شريط تمرير، القيمة ","slider, value ")+e.value;if(t==="INPUT"||t==="TEXTAREA")return L("مربع كتابة","text box");return ""}
function labelOf(e){var l=e.getAttribute("aria-label");if(l)return l;if(e.id){var lb=document.querySelector('label[for="'+e.id+'"]');if(lb)return lb.textContent.trim()}if(e.labels&&e.labels[0])return e.labels[0].textContent.trim();return (e.textContent||e.value||e.placeholder||"").trim().slice(0,140)}
document.addEventListener("focusin",function(ev){if(!S.a11y.blind)return;var e=ev.target;if(!e||!e.matches)return;if(!e.matches("a,button,input,select,textarea,[role=switch],[role=checkbox],[tabindex]"))return;var t=labelOf(e);if(t)speak(t+"، "+roleWord(e),uiLang(),null)});
document.addEventListener("keydown",function(ev){if(!S.a11y.blind)return;var tg=ev.target,typing=tg&&((tg.tagName==="INPUT"&&["file","checkbox","range","radio"].indexOf(tg.type)<0)||tg.tagName==="TEXTAREA"||tg.tagName==="SELECT");
  if(ev.key==="Escape"){stopSpeak();return}if(typing||ev.ctrlKey||ev.metaKey||ev.altKey)return;var k=ev.key.toLowerCase();
  if(/^[1-9]$/.test(k)){var it=shortcutTargets()[+k-1];if(!it)return;ev.preventDefault();if(it[0].indexOf("role:")===0){var b=document.querySelector('[data-act=role][data-r="'+it[0].slice(5)+'"]');if(b)b.click()}else go(it[0]);return}
  if(k==="r"||k==="ق"){ev.preventDefault();readPage();return}
  if(k==="h"||k==="ح"){ev.preventDefault();shortcutHelp();return}
  if(k==="b"||k==="ر"){ev.preventDefault();goBack();return}});

/* ---------- routing ---------- */
var VIEWS={start:vStart,schedule:vSchedule,kids:vKids,voice:vVoice,school:vSchool,learn:vLearn,settings:vSettings,ask:vAsk,privacy:vPrivacy,progress:vProgress,worksheet:vWorksheet,chat:vChat,home:vHome,about:vAbout,login:vLogin,needs:vNeeds,quiz:vQuiz,student:vStudent,videos:vVideos,tools:vTools,passport:vPassport,platform:vPlatform,verify:vVerify,parent:vParent,classes:vClasses,teacher:vTeacher,gate:vGate,secure:vSecure};
var ACCESS={schedule:"student",kids:"parent",voice:"parent",learn:"student",ask:"parent",privacy:"parent",progress:"teacher",worksheet:"teacher",chat:"parent|teacher",needs:"student",quiz:"student",student:"student",videos:"student",tools:"student",passport:"student",platform:"student",verify:"parent",parent:"parent",classes:"teacher",teacher:"teacher"};
function homeFor(){if(S.role==="student")return !S.needsDone?"needs":!S.quiz?"quiz":!S.passportDone?"passport":"student";if(S.role==="parent")return S.verified?"parent":"verify";if(S.role==="teacher")return S.classes.length?"teacher":"classes";return "home"}
function render(keep){
  if(S.view!=="tools")clearInterval(audTimer);
  stopSpeak();var r=document.documentElement;r.lang=S.lang;r.dir=S.lang==="ar"?"rtl":"ltr";
  var body=(VIEWS[S.view]||vHome)();document.getElementById("app").innerHTML=(S.authed&&S.view!=="secure")?'<div class="shell">'+sidebar()+'<div class="content">'+backBar()+body+'<p class="dfoot">'+L("نموذج أولي للهاكاثون. كل البيانات والأنظمة تجريبية.","Hackathon prototype. All data and systems are simulated.")+'</p></div></div>':header()+backBar()+body;
  floatUI();renderExp();renderPFeed();renderChat();renderTransfer();renderWS();decorate();applyA11y();
  if(!keep){window.scrollTo(0,0);var h1=document.querySelector("main h1");if(h1){h1.setAttribute("tabindex","-1");if(S.a11y.blind||document.activeElement===document.body)try{h1.focus({preventScroll:true})}catch(e){}}
    if(S.view!=="secure"&&S.view!=="gate"){var ttl=h1?h1.textContent.trim():"";liveSay(L("صفحة: ","Page: ")+ttl);if(S.a11y.blind)setTimeout(function(){blindSpeak(pageSummary())},250)}}}
var navStack=[];
function backBar(){var v=S.view;if(["home","student","parent","teacher","secure"].indexOf(v)>=0)return "";
  if(S.authed&&S.role==="student"&&!S.passportDone&&(v==="needs"||v==="quiz"))return "";
  if(v==="verify"&&!S.verified)return "";if(v==="classes"&&!S.classes.length)return "";
  return '<div class="wrap backbar"><button class="btn" data-act="back">'+ic("arrow")+L("رجوع","Back")+'</button></div>'}
function goBack(){if(S.view==="videos"&&S.vid){S.vid=null;render();return}
  navStack.pop();var skip=S.authed?["login","school","gate"]:["gate"],prev;
  do{prev=navStack.pop()}while(prev&&(skip.indexOf(prev)>=0||prev===S.view));
  go(prev||(S.authed?homeFor():"home"))}
var pendingScroll=null;
function route(){
  var h=(location.hash||"").replace("#","");
  if(S.view==="secure"&&h!==S.secureRoute){S.secure=null}
  if(h&&!VIEWS[h]&&h.length<64&&window.crypto&&crypto.subtle){digest(h).then(function(d){if(d===K.r){S.secureRoute=h;S.view=S.secure?"secure":"gate"}else S.view="home";render()}).catch(function(){S.view="home";render()});return}
  var v=VIEWS[h]&&h!=="gate"&&h!=="secure"?h:"home";
  if(ACCESS[v]){
    if(!S.authed){v="home";setTimeout(function(){toast(L("سجّل الدخول أولًا.","Please sign in first."),"lock")},50)}
    else if(ACCESS[v].split("|").indexOf(S.role)<0){v=homeFor();setTimeout(function(){toast(L("هذه الصفحة غير متاحة لنوع حسابك.","This page isn't available for your account type."),"lock")},50)}
    else if(v==="tools"&&!hasPOD())v="student";
    else if(S.role==="student"&&["needs","quiz","passport","platform","settings"].indexOf(v)<0&&(!S.needsDone||!S.quiz||!S.passportDone))v=homeFor();
  }
  if(v==="login"&&(!S.role||S.authed))v=S.authed?homeFor():"home";
  if(v==="login"&&S.role!=="parent"&&!S.school)v="school";
  if(v==="school"&&(!S.role||S.role==="parent"||S.authed))v=S.authed?homeFor():(S.role==="parent"?"login":"home");
  if(v==="needs")tmpNeeds=null;
  if(v==="verify"&&S.vstage==="checking"){clearTimeout(vTimer);vTimer=setTimeout(function(){S.vstage="found";if(S.view==="verify")render(true)},1500)}
  if(v!=="videos")S.vid=null;
  if(h&&v!==h&&VIEWS[h]){location.replace("#"+v);return}
  if(navStack[navStack.length-1]!==v){navStack.push(v);if(navStack.length>30)navStack.shift()}
  S.view=v;render();
  if(pendingScroll){var id=pendingScroll;pendingScroll=null;setTimeout(function(){var el=document.getElementById(id);if(el)el.scrollIntoView({block:"start"})},60)}}
function go(view,scrollId){pendingScroll=scrollId||null;if(location.hash==="#"+view)route();else location.hash=view}
function logout(msg,stay){stopSpeak();clearInterval(audTimer);S.authed=false;S.role=null;S.method=null;S.needs=[];S.needsDone=false;S.quiz=null;S.verified=false;S.kids={sara:false,omar:false};S.extraReq=[];S.passportDone=false;S.school=null;S.perf=0;S.rel="father";S.replyTo=null;S.classes=[];S.tclass=null;S.vstage="checking";S.qi=0;S.qa={};S.qstage="q";S.chat=[];S.exp={lesson:false,para:null,mode:null,ans:{},interact:{}};S.transfer="pending";S.ws={topic:"frac",level:"mid",state:"idle",reviewed:false,sent:false};S.a11y=Object.assign({},DEF_A11Y);applyA11y();persist();if(stay)return;go("home");if(msg)setTimeout(function(){toast(msg,"lock")},80)}
function perfUpdate(mode){var k=MODEFMT[mode];if(!k||!S.quiz)return;var p=S.quiz.pct;p[k]+=6;var tot=0;Object.keys(p).forEach(function(x){tot+=p[x]});Object.keys(p).forEach(function(x){p[x]=Math.round(p[x]/tot*100)});var o=Object.keys(p).sort(function(a,b){return p[b]-p[a]});S.quiz.primary=o[0];S.quiz.secondary=o[1];S.perf=(S.perf||0)+1;persist();setTimeout(function(){toast(L("تحدّث ملفك من أدائك الفعلي.","Your profile was updated from your actual results."),"spark")},200)}
function presetStudent(){S.school=S.school||{name:T(SCHOOL),emirate:"auh",city:L("العين","Al Ain")};S.role="student";S.authed=true;S.method="demo";if(!S.needsDone){S.needs=["dyslexia","hearing"];S.needsDone=true;applyNeeds(S.needs)}if(!S.quiz)S.quiz=computeQuiz(SAMPLE_ANS);S.passportDone=true;persist()}
function applyNeeds(list){list.forEach(function(k){var n=NEEDS.find(function(x){return x.k===k});if(n)Object.keys(n.set).forEach(function(s){S.a11y[s]=n.set[s]})});applyA11y()}

/* ---------- session timeout ---------- */
var lastAct=Date.now();
["click","keydown","pointerdown","scroll"].forEach(function(e){document.addEventListener(e,function(){lastAct=Date.now();if(S.authed&&sessTick++%20===0)persist()},{passive:true})});
var sessTick=0;
setInterval(function(){if(Date.now()-lastAct>TIMEOUT){if(S.authed)logout(L("سُجّل خروجك تلقائيًا بعد 10 دقائق دون نشاط لحماية حسابك.","You were signed out after 10 idle minutes to protect your account."));if(S.secure){S.secure=null;S.view="home";location.hash="home"}}},20000);

/* ---------- events ---------- */
document.addEventListener("click",function(ev){
  var t=ev.target.closest("[data-act]");if(!t)return;var a=t.getAttribute("data-act");
  if(a==="guide-close"&&ev.target.closest("[data-stop]")&&!ev.target.closest("button[data-act=guide-close]"))return;
  switch(a){
  case "back":goBack();break;
  case "blind":S.a11y.blind=!S.a11y.blind;if(S.a11y.blind){S.a11y.read=true;S.a11y.voice=true}applyA11y();render(true);setTimeout(function(){blindSpeak(S.a11y.blind?L("تم تفعيل وضع المكفوفين. ","Blind mode is on. ")+pageSummary():L("تم إيقاف وضع المكفوفين.","Blind mode is off."))},150);break;
  case "skip":ev.preventDefault();var mm=document.querySelector("main h1")||document.getElementById("main");if(mm){mm.setAttribute("tabindex","-1");mm.focus()}break;
  case "lang":S.lang=S.lang==="ar"?"en":"ar";save("lang",S.lang);render(true);break;
  case "theme":document.documentElement.setAttribute("data-theme",isDark()?"light":"dark");render(true);break;
  case "nav":go(t.getAttribute("data-to"));break;
  case "logout":logout(L("تم تسجيل الخروج.","Signed out."));break;
  case "role":var nr=t.getAttribute("data-r");if(S.authed){logout(null,true);}S.role=nr;S.schoolErr="";S.login={step:"start",email:"",code:null,exp:0,tries:0,err:""};go(nr==="parent"?"login":"school");break;
  case "l-id":S.login.step="id";render(true);setTimeout(function(){if(S.view==="login"&&S.login.step==="id")signedIn("uaepass")},1300);break;
  case "l-back":S.login={step:"start",email:"",code:null,exp:0,tries:0,err:""};render(true);break;
  case "need":var k=t.getAttribute("data-k");if(k==="none")tmpNeeds=tmpNeeds.indexOf("none")>=0?[]:["none"];else{tmpNeeds=tmpNeeds.filter(function(x){return x!=="none"});var ix=tmpNeeds.indexOf(k);if(ix>=0)tmpNeeds.splice(ix,1);else tmpNeeds.push(k)}render(true);break;
  case "needs-done":if(S.passportDone){S.needs=tmpNeeds.slice();applyNeeds(S.needs);persist();go("passport");break}S.needs=tmpNeeds.slice();S.needsDone=true;applyNeeds(S.needs);if(hasPOD()){ssave("pending",{needs:S.needs.filter(function(k){return k!=="none"}),state:"pending"});setTimeout(function(){toast(L("أُرسل اختيارك إلى ولي أمرك ليؤكده.","Your choice was sent to your parent to confirm."),"users")},300)}if(S.quiz)S.quiz=computeQuiz(S.qa&&Object.keys(S.qa).length?S.qa:SAMPLE_ANS);persist();go(S.quiz?"student":"quiz");break;
  case "edit-needs":go("needs");break;
  case "qa":S.qa[S.qi]=t.getAttribute("data-v");render(true);break;
  case "qback":S.qi=Math.max(0,S.qi-1);render(true);break;
  case "qnext":if(S.qi<QZ.length-1){S.qi++;render(true)}else{S.qstage="analyzing";render(true);setTimeout(function(){S.quiz=computeQuiz(S.qa);S.qstage="result";persist();if(S.view==="quiz")render(true)},1600)}break;
  case "quiz-finish":S.exp.mode=null;if(S.passportDone){S.qstage="q";S.qi=0;go("student")}else go("passport");break;
  case "passport-done":S.passportDone=true;S.qstage="q";S.qi=0;persist();go("student");toast(L("جاهز! جوازك يعمل الآن في كل المنصات.","All set! Your passport now works on every platform."),"pass");break;
  case "quiz-retake":S.quiz=null;S.qa={};S.qi=0;S.qstage="q";persist();go("quiz");break;
  case "exp-lesson":S.exp.lesson=true;renderExp();break;
  case "exp-para":S.exp.counted=false;S.exp.para=+t.getAttribute("data-i");if(!S.exp.mode&&S.quiz)S.exp.mode=FMT[S.quiz.primary].mode;S.exp.ans={};renderExp();break;
  case "exp-mode":S.exp.mode=t.getAttribute("data-m");S.exp.ans={};S.exp.counted=false;renderExp();break;
  case "exp-play":var at=document.getElementById("exp-audio-text");if(at)speak(at.textContent,uiLang(),at);break;
  case "exp-ans":S.exp.ans[+t.getAttribute("data-q")]=+t.getAttribute("data-o");if(!S.exp.counted&&QS.every(function(q,i){return S.exp.ans[i]===q.a})){S.exp.counted=true;perfUpdate(S.exp.mode)}renderExp();break;
  case "exp-int":S.exp.interact[t.getAttribute("data-k")]=t.getAttribute("data-v");renderExp();break;
  case "report":toast(L("شكرًا. أُرسل البلاغ للمراجعة.","Thanks. The report was sent for review."),"flag");break;
  case "vopen":S.vid=t.getAttribute("data-id");S.vtab=S.quiz&&S.quiz.primary==="h"?"act":S.quiz&&S.quiz.primary==="v"?"img":"text";if(S.view!=="videos")go("videos");else render();break;
  case "vclose":S.vid=null;render();break;
  case "vtab":S.vtab=t.getAttribute("data-t");render(true);break;
  case "vfilter":S.vfilter=t.getAttribute("data-f");render(true);break;
  case "vq":S.vq[t.getAttribute("data-k")]=+t.getAttribute("data-o");render(true);break;
  case "vplay":var vv=VIDS.find(function(x){return x.id===S.vid});var was=S.a11y.captions;S.a11y.captions=true;speak(T(vv.tr),uiLang(),null,function(){S.a11y.captions=was});break;
  case "sign":S.sign={sel:+t.getAttribute("data-i"),state:"proc",text:"",upload:false};render(true);setTimeout(function(){S.sign.state="done";S.sign.text=T(SIGNS[S.sign.sel]);if(S.view==="tools")render(true)},1300);break;
  case "sign-say":speak(S.sign.text,uiLang(),document.getElementById("sign-txt"));break;
  case "sign-send":toast(L("أُرسلت الرسالة إلى معلمتك.","Message sent to your teacher."),"chat");break;
  case "aud":runAud(+t.getAttribute("data-i"),false);break;
  case "copy":var cs=document.getElementById(t.getAttribute("data-src"));if(cs){var txt=cs.innerText;try{navigator.clipboard.writeText(txt).then(function(){toast(L("تم النسخ.","Copied."),"copy")},function(){selectText(cs)})}catch(e){selectText(cs)}}break;
  case "a11y":var ak=t.getAttribute("data-k");S.a11y[ak]=!S.a11y[ak];t.setAttribute("aria-checked",S.a11y[ak]);applyA11y();break;
  case "kid":var kk=t.getAttribute("data-k");S.kids[kk]=!S.kids[kk];render(true);break;
  case "verify-done":S.verified=true;S.child=kidsList()[0];persist();go("parent");break;
  case "child":S.child=t.getAttribute("data-c");render(true);break;
  case "sum-play":if(S.sumPlaying){stopSpeak();break}var wv=document.getElementById("waves");if(wv)wv.classList.add("on");var sm=SUMMARY[S.sumLang];speak(sm.t,sm.code,document.getElementById("sum-text"),function(){S.sumPlaying=false;var bb=document.getElementById("sum-play");if(bb)bb.innerHTML=ic("play")+L("استمع إلى الملخص","Play summary")});S.sumPlaying=true;t.innerHTML=ic("stop")+L("إيقاف","Stop");break;
  case "ask":var qi=+t.getAttribute("data-i");S.chat.push({me:1,t:T(CHATQ[qi].q)});S.chat.push({i:qi});renderChat();break;
  case "consent":var ck=t.getAttribute("data-k");S.consent[ck]=!S.consent[ck];t.setAttribute("aria-checked",S.consent[ck]);renderPFeed();toast(S.consent[ck]?L("أُعيدت المشاركة.","Sharing is back on."):L("أوقفت المشاركة مع هذه الخدمة.","Sharing with this service stopped."),"lock");break;
  case "tr-ok":S.transfer="approved";renderTransfer();break;
  case "tr-undo":S.transfer="pending";renderTransfer();break;
  case "cls":S.classes.push(t.getAttribute("data-id"));persist();render(true);break;
  case "cls-report":toast(L("أُرسل البلاغ إلى إدارة المدرسة.","Report sent to the school administration."),"flag");break;
  case "cls-done":S.tclass=S.classes[0];go("teacher");break;
  case "tcl":S.tclass=t.getAttribute("data-id");render(true);break;
  case "ws-support":S.ws={topic:"frac",level:"basic",state:"idle",reviewed:false,sent:false};go("worksheet");break;
  case "ws-play":var wa=document.getElementById("ws-audio");if(wa)speak(wa.textContent,uiLang(),null);break;
  case "ws-send":S.ws.sent=true;renderWS();break;
  case "guide":S.guide=true;floatUI();applyA11y();break;
  case "guide-close":S.guide=false;floatUI();applyA11y();break;
  case "g1":S.guide=false;logout();break;
  case "g2":S.guide=false;S.role="student";S.authed=true;S.method="demo";S.school={name:T(SCHOOL),emirate:"auh",city:L("العين","Al Ain")};S.needs=[];S.needsDone=false;S.quiz=null;S.passportDone=false;S.qa={};S.qi=0;S.qstage="q";persist();go("needs");break;
  case "g3":S.guide=false;presetStudent();S.vid=null;go("videos");break;
  case "g4":S.guide=false;presetStudent();go("tools");break;
  case "g5":S.guide=false;presetStudent();go("passport");break;
  case "g6b":S.guide=false;S.role="parent";S.authed=true;S.method="demo";S.verified=true;S.kids={sara:true,omar:true};S.sumLang="ur";persist();go("voice");break;
  case "g6":S.guide=false;S.role="parent";S.authed=true;S.method="demo";S.verified=false;S.kids={sara:false,omar:false};S.vstage="checking";persist();go("verify");break;
  case "g8":S.guide=false;S.role="parent";S.authed=true;S.method="demo";S.verified=true;S.kids={sara:true,omar:true};S.cg="g7b";persist();go("chat");break;
  case "g7":S.guide=false;S.role="teacher";S.authed=true;S.method="demo";S.classes=[];S.school=S.school||{name:T(SCHOOL),emirate:"auh",city:L("العين","Al Ain")};persist();go("classes");break;
  case "vc":var v=t.getAttribute("data-v");toast(L("سمعتُ أمرك (محاكاة).","Command heard (simulated)."),"mic");if(v==="home")go(homeFor());else if(v==="vid"&&S.role==="student")go("videos");else if(v==="back")goBack();else if(v==="help")shortcutHelp();else readPage();break;
  case "need-iep":tmpNeeds=["dyslexia"];render(true);toast(L("استُوردت من خطتك التعليمية الفردية (محاكاة).","Imported from your individual education plan (simulated)."),"doc");break;
  case "palette":save("palette",t.getAttribute("data-p"));applyPrefs();render(true);break;
  case "thememode":save("thememode",t.getAttribute("data-v"));applyPrefs();render(true);break;
  case "setlang":S.lang=t.getAttribute("data-v");save("lang",S.lang);render(true);break;
  case "motion":save("motion",load("motion","on")==="on"?"off":"on");applyPrefs();render(true);break;
  case "pend-ok":var pn=pendingNeeds();pn.state="confirmed";ssave("pending",pn);render(true);toast(L("تم التأكيد. سترى المعلمات ما تحتاجه سارة فقط.","Confirmed. Teachers will see only what Sara needs."),"check");break;
  case "pend-talk":toast(L("أُرسل طلبك إلى المدرسة لتحديد موعد.","Your request was sent to the school to set a time."),"cal");break;
  case "needs-delete":ssave("pending",{needs:[],state:"deleted"});toast(L("حُذف سجل احتياجات الدعم.","The support-needs record was deleted."),"check");break;
  case "interp":toast(L("أُرسل طلب مترجم لغة الإشارة للحصة القادمة.","Interpreter request sent for the next class."),"users");break;
  case "cg":S.cg=t.getAttribute("data-g");S.replyTo=null;render(true);break;
  case "reply":S.replyTo=+t.getAttribute("data-i");render(true);setTimeout(function(){var x=document.getElementById("m-text");if(x)x.focus()},30);break;
  case "reply-cancel":S.replyTo=null;render(true);break;
  case "set-state":var tg=document.getElementById(t.getAttribute("data-t"));if(tg){tg.textContent=t.getAttribute("data-v");tg.className="tag "+(t.getAttribute("data-c")||"")}var grp=t.closest(".acts");if(grp)grp.querySelectorAll("button").forEach(function(b){b.disabled=true});break;
  case "show-panel":var root=document.getElementById("secure-root");if(!root)break;var p=t.getAttribute("data-p");root.querySelectorAll(".spanel").forEach(function(x){x.hidden=x.id!==p});t.parentNode.querySelectorAll("[role=tab]").forEach(function(x){x.setAttribute("aria-selected",x===t)});break;
  case "close-secure":S.secure=null;go("home");break;
  }
});
function selectText(el){try{var r=document.createRange();r.selectNodeContents(el);var s=getSelection();s.removeAllRanges();s.addRange(r);toast(L("حدّدتُ النص. انسخه يدويًا.","Text selected. Copy it manually."),"copy")}catch(e){}}
document.addEventListener("input",function(ev){var t=ev.target,k=t.getAttribute("data-in");if(k==="font"){S.a11y.font=+t.value;var o=document.getElementById("a-font-out");if(o)o.textContent=t.value+"%";applyA11y()}});
document.addEventListener("change",function(ev){var t=ev.target,k=t.getAttribute("data-in");if(!k)return;
  if(k==="sumlang"){stopSpeak();S.sumLang=t.value;var sm=SUMMARY[t.value],tx=document.getElementById("sum-text");tx.textContent=sm.t;tx.dir=sm.dir;tx.lang=sm.code}
  if(k==="wstopic"){S.ws.topic=t.value;if(S.ws.state==="done"){S.ws.sent=false;S.ws.reviewed=false;renderWS()}}
  if(k==="wslevel"){S.ws.level=t.value}
  if(k==="emirate"){var sn=document.getElementById("s-name").value,sc=document.getElementById("s-city").value;S.school={name:sn,emirate:t.value,city:sc};render(true)}
  if(k==="rel"){S.rel=t.value;persist();render(true)}
  if(k==="trinc"){S.trInc[t.getAttribute("data-k")]=t.checked}
  if(k==="wsrev"){S.ws.reviewed=t.checked;renderWS()}
  if(k==="exp-upload"&&t.files&&t.files[0]){toast(L("تم رفع الصفحة (محاكاة): العلوم، الدرس 4","Page uploaded (simulated): Science, Lesson 4"),"upload");S.exp.lesson=true;renderExp()}
  if(k==="sign-upload"&&t.files&&t.files[0]){S.sign={sel:1,state:"proc",text:"",upload:true};render(true);setTimeout(function(){S.sign.state="done";S.sign.text=T(SIGNS[1]);if(S.view==="tools")render(true)},1800)}
  if(k==="aud-upload"&&t.files&&t.files[0]){runAud(0,true)}
});
document.addEventListener("submit",function(ev){var f=ev.target.getAttribute("data-form");if(!f)return;ev.preventDefault();
  if(f==="email"){var em=(document.getElementById("l-email").value||"").trim();
    if(!/^[^\s@<>"']{1,64}@[A-Za-z0-9.-]{2,}\.[A-Za-z]{2,}$/.test(em)){S.login.err=L("اكتب بريدًا إلكترونيًا صحيحًا، مثل student.name@school.ae","Enter a valid email, such as student.name@school.ae");render(true);return}
    S.login={step:"code",email:em,code:newCode(),exp:Date.now()+5*60000,tries:0,err:""};render(true);setTimeout(function(){var c=document.getElementById("l-code");if(c)c.focus()},30)}
  if(f==="code"){var lg=S.login,v=(document.getElementById("l-code").value||"").trim();
    if(Date.now()>lg.exp){lg.err=L("انتهت صلاحية الرمز. اطلب رمزًا جديدًا.","The code has expired. Request a new one.");lg.tries=3}
    else if(v===lg.code){signedIn("email");return}
    else{lg.tries++;lg.err=lg.tries>=3?L("انتهت المحاولات. ارجع واطلب رمزًا جديدًا.","No attempts left. Go back and request a new code."):L("الرمز غير صحيح. بقيت "+(3-lg.tries)+" محاولة.","Wrong code. "+(3-lg.tries)+" attempt(s) left.")}
    render(true)}
  if(f==="kidreq"){var kid=(document.getElementById("k-id").value||"").replace(/\D/g,"").slice(0,12),kc=(document.getElementById("k-code").value||"").trim();if(kid.length<4||kc.length<4){toast(L("أكمل رقم الطالب ورمز الربط.","Fill in the student number and link code."),"alert");return}S.extraReq.push("••••"+kid.slice(-4));persist();render(true);toast(L("أُرسل الطلب إلى المدرسة.","Request sent to the school."),"shield")}
  if(f==="chat"){var inp=document.getElementById("chat-q"),q=inp.value.trim().slice(0,200);if(!q)return;S.chat.push({me:1,t:q});var n=q.replace(/[؟?\s]/g,"").toLowerCase(),hit=-1;CHATQ.forEach(function(c,i){if(c.q[0].replace(/[؟?\s]/g,"")===n||c.q[1].replace(/[?\s]/g,"").toLowerCase()===n)hit=i});S.chat.push({i:hit});inp.value="";renderChat()}
  if(f==="school"){var nm=document.getElementById("s-name").value.trim().slice(0,80),em=document.getElementById("s-em").value,ct=document.getElementById("s-city").value.trim().slice(0,60);
    if(nm.length<3||!em||ct.length<2){S.school={name:nm,emirate:em,city:ct};S.schoolErr=L("اكتب اسم المدرسة، واختر الإمارة، واكتب المدينة أو المنطقة.","Enter the school name, choose the emirate, and enter the city or area.");render(true);return}
    S.school={name:nm,emirate:em,city:ct};S.schoolErr="";go("login")}
  if(f==="msg"){var ta=document.getElementById("m-text"),raw=(ta.value||"").trim().slice(0,500);if(!raw)return;var mk=maskContact(raw),ms=sload("msgs",[]),teacherR=S.role==="teacher";
    var rt=S.replyTo!=null?allMsgs()[S.replyTo]:null;
    var m={g:S.cg,from:teacherR?"teacher":"parent",user:true,text:mk.t,masked:mk.masked};
    if(teacherR){if(rt){m.priv=!!rt.priv;m.kid=rt.priv?rt.kid:undefined;if(rt.user){var ix=S.replyTo-MSG_SEED.length;if(ms[ix])ms[ix].answered=true}}}
    else{m.kid=S.cg==="g7b"?"sara":"omar";m.priv=document.getElementById("m-priv").checked}
    ms.push(m);ssave("msgs",ms);S.replyTo=null;render(true);var box=document.getElementById("msgs");if(box)box.scrollTop=box.scrollHeight;toast(teacherR?L("أُرسل الرد.","Reply sent."):L("أُرسلت رسالتك. الرد خلال يوم عمل.","Message sent. You'll get a reply within one working day."),"chat")}
  if(f==="ws"){S.ws.state="loading";S.ws.sent=false;S.ws.reviewed=false;renderWS();setTimeout(function(){S.ws.state="done";renderWS()},1200)}
  if(f==="gate"){var a=att(),msg=document.getElementById("g-msg"),inpG=document.getElementById("g-pass"),code=inpG.value;inpG.value="";
    if(a.until>Date.now())return;
    openSecure(code).then(function(data){ssave("ga",{n:0,until:0});S.secure=data;S.view="secure";render()}).catch(function(){a.n++;if(a.n>=5){a.until=Date.now()+60000;a.n=0}ssave("ga",a);
      msg.innerHTML='<span class="errbox">'+ic("alert")+'<span>'+(a.until>Date.now()?L("تم إيقاف المحاولات مؤقتًا. حاول بعد دقيقة.","Attempts are paused. Try again in a minute."):L("رمز غير صحيح.","Incorrect code."))+'</span></span>';if(a.until>Date.now())render(true)})}
});
